selector_to_html = {"a[href=\"#id5\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u9519\u8bef<a class=\"headerlink\" href=\"#id5\" title=\"Link to this heading\">#</a></h2><p>\u6240\u6709\u7c7b\u522b\u90fd\u7ee7\u627f <code class=\"docutils literal notranslate\"><span class=\"pre\">FlagQuantumError</span></code> \u4ee5\u53ca\u4e00\u4e2a\u517c\u5bb9\u7684 Python \u5185\u7f6e\u5f02\u5e38\u3002\u7c7b\u578b\u9519\u8bef\u4e0e\u672a\u77e5\u5173\u952e\u5b57\u53c2\u6570\u629b\u51fa <code class=\"docutils literal notranslate\"><span class=\"pre\">TypeError</span></code>\u3002</p>", "a[href=\"#id4\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u7b97\u5b50<a class=\"headerlink\" href=\"#id4\" title=\"Link to this heading\">#</a></h2><p>\u7ebf\u8def\u64cd\u4f5c\u4e0e\u540e\u7aef\u964d\u7ea7\u80fd\u529b\u6765\u81ea\u540c\u4e00\u4efd\u5e26\u7c7b\u578b\u7684\u7b97\u5b50\u6ce8\u518c\u8868\u3002\u6ce8\u518c\u4e86\u67d0\u4e2a\u540e\u7aef\u7684\u964d\u7ea7\uff0c\u53ea\u610f\u5473\u7740\u8be5\u7b97\u5b50\u53ef\u4ee5\u4e3a\u8fd9\u4e2a\u540e\u7aef\u964d\u7ea7\u2014\u2014\u5b83\u4e0d\u662f\u53d1\u5e03\u8bc1\u636e\u3002\u4ed3\u5e93\u4e2d\u751f\u6210\u7684\u7b97\u5b50\u8868\u662f\u6ce8\u518c\u96c6\u5408\u7684\u6743\u5a01\u6765\u6e90\uff0c\u8986\u76d6\u6ce1\u5229\u95e8\u3001Clifford \u95e8\u3001\u65cb\u8f6c\u95e8\u3001\u53d7\u63a7\u95e8\u3001\u5bf9\u79f0\u53cc\u6bd4\u7279\u95e8\u4e0e\u76f8\u4f4d\u95e8\uff0c\u4ee5\u53ca\u7a33\u5b9a\u566a\u58f0\u6a21\u578b\u6240\u7528\u7684\u566a\u58f0\u4fe1\u9053\u3002</p>", "a[href=\"#id7\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u5ef6\u4f38\u9605\u8bfb<a class=\"headerlink\" href=\"#id7\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#id6\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u7a33\u5b9a\u6027\u8fb9\u754c<a class=\"headerlink\" href=\"#id6\" title=\"Link to this heading\">#</a></h2>", "a[href=\"capabilities.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u80fd\u529b\u53c2\u8003<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h1><p>FlagQuantum \u516c\u5f00\u6bcf\u4e2a\u80fd\u529b\u7684\u6210\u719f\u5ea6\uff0c\u800c\u4e0d\u662f\u9760\u793a\u4f8b\u53bb\u6697\u793a\u3002\u672c\u9875\u662f\u6458\u8981\uff1b\u4ed3\u5e93\u4e2d\u7ecf\u673a\u5668\u6821\u9a8c\u7684\u80fd\u529b\u77e9\u9635\u624d\u662f\u6743\u5a01\u6765\u6e90\u3002</p>", "a[href=\"#id3\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u8fd0\u884c\u65f6\u914d\u7f6e<a class=\"headerlink\" href=\"#id3\" title=\"Link to this heading\">#</a></h2><p><code class=\"docutils literal notranslate\"><span class=\"pre\">RuntimeConfig</span></code> \u662f FlagQuantum \u7684\u4e0d\u53ef\u53d8\u6267\u884c\u7b56\u7565\uff1a\u540e\u7aef\u3001\u8bbe\u5907\u3001\u5b9e\u6570\u4e0e\u590d\u6570\u7cbe\u5ea6\u3001JAX \u7cbe\u5ea6\u3001\u77e9\u9635\u4e58\u6cd5\u7b56\u7565\u4e0e\u7ed8\u5236\u98ce\u683c\u3002<code class=\"docutils literal notranslate\"><span class=\"pre\">Circuit</span></code> \u5728\u6784\u9020\u65f6\u6355\u83b7\u914d\u7f6e\uff0c\u5e76\u628a\u7248\u672c\u5316\u6e05\u5355\u5d4c\u5165 IR \u4e0e\u6267\u884c\u89c4\u5212\u4e2d\uff0c\u56e0\u6b64\u5206\u5e03\u5f0f\u5de5\u4f5c\u8fdb\u7a0b\u53ef\u4ee5\u91cd\u5efa\u540c\u4e00\u5957\u7b56\u7565\u3002</p>", "a[href=\"#id1\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u53c2\u8003\u8d44\u6599<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h1><p>\u7a33\u5b9a\u63a5\u53e3\u3001\u914d\u7f6e\u4e0e\u652f\u6301\u8fb9\u754c\u3002</p>", "a[href=\"#api\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u7a33\u5b9a API<a class=\"headerlink\" href=\"#api\" title=\"Link to this heading\">#</a></h2><p>FlagQuantum \u53ea\u66b4\u9732\u4e00\u5957\u7ecf\u8fc7\u6574\u7406\u7684 Python \u63a5\u53e3\uff0c\u5373 <code class=\"docutils literal notranslate\"><span class=\"pre\">import</span> <span class=\"pre\">flagquantum</span> <span class=\"pre\">as</span> <span class=\"pre\">fq</span></code>\u3002\u7a33\u5b9a\u540d\u79f0\u7531\u53d7\u68c0\u6e05\u5355\u5708\u5b9a\uff0c\u5e76\u7531\u53ef\u6267\u884c\u7684\u5951\u7ea6\u6d4b\u8bd5\u9a8c\u8bc1\u3002</p>", "a[href=\"../FlagQuantum_overview/architecture.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u67b6\u6784<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h1><p>FlagQuantum \u4e3a\u91cf\u5b50 AI \u7a0b\u5e8f\u5728\u672c\u5730\u5f00\u53d1\u3001\u52a0\u901f\u5185\u6838\u3001\u5206\u5e03\u5f0f\u6a21\u62df\u5230\u90e8\u7f72\u4e4b\u95f4\u63d0\u4f9b\u540c\u4e00\u5957\u516c\u5f00\u6a21\u578b\u3002\u5b83\u7684\u7ec4\u7ec7\u65b9\u5f0f\u4fdd\u8bc1\u540e\u7aef\u53d8\u5316\u4e0d\u4f1a\u6539\u53d8\u7a0b\u5e8f\u542b\u4e49\u3002</p>", "a[href=\"#id2\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">API \u5bf9\u7167<a class=\"headerlink\" href=\"#id2\" title=\"Link to this heading\">#</a></h2>"}
